import{_ as s,y as r,a as h,o as t,a4 as a,c as i,w as o,I as n,D as p,a5 as c}from"./chunks/framework.-FZumj2l.js";const w=JSON.parse('{"title":"Checkout Workflow (Shop)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/checkout.md","filePath":"api/workflows/shop/checkout.md","lastUpdated":1784902076000}'),l={name:"api/workflows/shop/checkout.md"};function m(u,e,g,y,f,k){const d=r("Mermaid");return t(),h("div",null,[e[1]||(e[1]=a('<h1 id="checkout-workflow-shop" tabindex="-1">Checkout Workflow (Shop) <a class="header-anchor" href="#checkout-workflow-shop" aria-label="Permalink to &quot;Checkout Workflow (Shop)&quot;">​</a></h1><p>Turn a ready cart into an order: set addresses, choose a shipping method, choose a payment method, place the order. A logged-in customer&#39;s saved addresses (and past orders) are surfaced so they can reuse them.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A cart with at least one item (<a href="/api/workflows/shop/cart.html">Cart workflow</a>).</li><li>A valid storefront key.</li></ul><h2 id="dependency-diagram" tabindex="-1">Dependency diagram <a class="header-anchor" href="#dependency-diagram" aria-label="Permalink to &quot;Dependency diagram&quot;">​</a></h2>',5)),(t(),i(c,null,{default:o(()=>[p(d,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20TD%0A%20%20cart%5BCart%20ready%3Cbr%2F%3Esee%20Cart%20workflow%5D%20--%3E%20ctx%7BCustomer%3Cbr%2F%3Elogged%20in%3F%7D%0A%20%20ctx%20--%20customer%20--%3E%20saved%5BGET%20checkout%20addresses%3Cbr%2F%3Esaved%20customer%20addresses%5D%0A%20%20ctx%20--%20guest%20--%3E%20billing%0A%20%20saved%20--%3E%20billing%5BPOST%20set%20billing%20address%5D%0A%20%20billing%20--%3E%20shipaddr%5BPOST%20set%20shipping%20address%5D%0A%20%20shipaddr%20--%3E%20shipm%5BGET%20shipping%20methods%5D%0A%20%20shipm%20--%3E%20setship%5BPOST%20set%20shipping%20method%5D%0A%20%20setship%20--%3E%20paym%5BGET%20payment%20methods%5D%0A%20%20paym%20--%3E%20setpay%5BPOST%20set%20payment%20method%5D%0A%20%20setpay%20--%3E%20place%5BPOST%20place%20order%5D%0A"})]),fallback:o(()=>e[0]||(e[0]=[n(" Loading... ",-1)])),_:1})),e[2]||(e[2]=a('<h2 id="ordered-call-table" tabindex="-1">Ordered call table <a class="header-anchor" href="#ordered-call-table" aria-label="Permalink to &quot;Ordered call table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Endpoint</th><th>Depends on</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td>Read saved addresses</td><td><a href="/api/rest-api/shop/checkout/get-addresses.html">GET addresses</a></td><td>logged-in customer</td><td>Customer path; prefill from saved. Past orders: <a href="/api/rest-api/shop/customer-orders.html">customer orders</a></td></tr><tr><td>2</td><td>Set billing address</td><td><a href="/api/rest-api/shop/checkout/set-billing-address.html">POST set-billing-address</a> · <a href="/api/graphql-api/shop/checkout.html">GraphQL</a></td><td>cart with items</td><td>Guest sends a full address; customer may reuse a saved one</td></tr><tr><td>3</td><td>Set shipping address</td><td><a href="/api/rest-api/shop/checkout/set-shipping-address.html">POST set-shipping-address</a></td><td>billing set</td><td></td></tr><tr><td>4</td><td>List shipping methods</td><td><a href="/api/rest-api/shop/checkout/get-shipping-methods.html">GET shipping-methods</a></td><td>shipping address set</td><td></td></tr><tr><td>5</td><td>Set shipping method</td><td><a href="/api/rest-api/shop/checkout/set-shipping-method.html">POST set-shipping-method</a></td><td>a chosen shipping method</td><td></td></tr><tr><td>6</td><td>List payment methods</td><td><a href="/api/rest-api/shop/checkout/get-payment-methods.html">GET payment-methods</a></td><td>shipping method set</td><td></td></tr><tr><td>7</td><td>Set payment method</td><td><a href="/api/rest-api/shop/checkout/set-payment-method.html">POST set-payment-method</a></td><td>a chosen payment method</td><td></td></tr><tr><td>8</td><td>Place order</td><td><a href="/api/rest-api/shop/checkout/place-order.html">POST place-order</a> · <a href="/api/graphql-api/shop/checkout.html">GraphQL</a></td><td>payment method set</td><td>Returns the created order</td></tr></tbody></table><blockquote><p><strong>GraphQL equivalents:</strong> the table links REST paths. Each step has a GraphQL operation (<code>createCheckoutAddress</code>, <code>collectionShippingRates</code>, <code>createCheckoutShippingMethod</code>, <code>collectionPaymentMethods</code>, <code>createCheckoutPaymentMethod</code>, <code>createCheckoutOrder</code>) — the full REST↔GraphQL list is on the <a href="/api/rest-graphql-mapping/shop/cart-checkout.html">Cart &amp; Checkout mapping</a>.</p></blockquote><h2 id="payment-methods-completing-the-order" tabindex="-1">Payment methods &amp; completing the order <a class="header-anchor" href="#payment-methods-completing-the-order" aria-label="Permalink to &quot;Payment methods &amp; completing the order&quot;">​</a></h2><p><code>GET payment-methods</code> returns whatever the store has enabled. There are two kinds, and the client handles them differently at <strong>set payment method</strong>:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Methods</th><th>What <code>set-payment-method</code> returns</th><th>Client action</th></tr></thead><tbody><tr><td><strong>On-site</strong></td><td><code>cashondelivery</code>, <code>moneytransfer</code></td><td><code>paymentGatewayUrl: null</code></td><td>Go straight to <strong>place-order</strong></td></tr><tr><td><strong>Offsite gateway</strong></td><td><code>stripe</code>, <code>payu</code>, <code>phonepe</code>, <code>razorpay</code>, <code>paypal_standard</code>, <code>paypal_smart_button</code></td><td>a non-null <code>paymentGatewayUrl</code></td><td><strong>Redirect</strong> the shopper to that URL; the order is created when they return to your success URL</td></tr></tbody></table><p>For an offsite gateway, pass your <code>paymentSuccessUrl</code> / <code>paymentFailureUrl</code> when setting the payment method, then redirect to <code>paymentGatewayUrl</code>. Do <strong>not</strong> call place-order yourself for those — the gateway&#39;s return flow finalises the order. On-site methods place the order directly.</p><div class="warning custom-block"><p class="custom-block-title">Offsite return (mobile / WebView clients)</p><p>The order row is created only when the shopper&#39;s browser lands on the store&#39;s <strong>success</strong> route after paying. If your app closes the payment view too early (before that return), the payment can succeed with no order created. Keep the view open until it reaches your success URL.</p></div><h2 id="end-to-end-sequence" tabindex="-1">End-to-end sequence <a class="header-anchor" href="#end-to-end-sequence" aria-label="Permalink to &quot;End-to-end sequence&quot;">​</a></h2><ul><li><strong>Customer:</strong> get-addresses → set-billing → set-shipping → get-shipping-methods → set-shipping-method → get-payment-methods → set-payment-method → <em>(on-site)</em> place-order <strong>or</strong> <em>(offsite)</em> redirect to <code>paymentGatewayUrl</code>.</li><li><strong>Guest:</strong> same, minus get-addresses (send a full billing / shipping address).</li></ul><p>Follow each linked endpoint page for the exact request / response body.</p><h2 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h2><p>To change checkout behavior on the server, see <a href="/api/workflows/customization/">Customization → Shop</a>.</p>',13))])}const T=s(l,[["render",m]]);export{w as __pageData,T as default};
